import json

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def filtered_majority(samples, min_variants=2):
    d = by_variant(samples)
    variant_sets = {}
    counts={}
    for s in samples:
        counts[s['answer']]=counts.get(s['answer'],0)+1
        variant_sets.setdefault(s['answer'], set()).add(s['variant'])
    eligible = {a:c for a,c in counts.items() if len(variant_sets[a])>=min_variants}
    pool = eligible if eligible else counts
    return max(pool.items(), key=lambda x:x[1])[0]

def majority_vote(samples):
    counts={}
    for s in samples: counts[s['answer']]=counts.get(s['answer'],0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

