import json, statistics

def top2_score_tiebreak(samples, ratio_thresh):
    counts={}
    scores={}
    for s in samples:
        counts[s['answer']]=counts.get(s['answer'],0)+1
        scores.setdefault(s['answer'],[]).append(s['score'])
    ranked = sorted(counts.items(), key=lambda x:-x[1])
    if len(ranked)==1:
        return ranked[0][0]
    top_a, top_c = ranked[0]
    second_a, second_c = ranked[1]
    if second_c >= ratio_thresh*top_c:
        avg_top = statistics.mean(scores[top_a])
        avg_second = statistics.mean(scores[second_a])
        return second_a if avg_second > avg_top else top_a
    return top_a

def majority_vote(samples):
    counts={}
    for s in samples: counts[s['answer']]=counts.get(s['answer'],0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

